popup.script:
(() => {
  const opener = document.querySelector('#reference-open');
  const panel = document.querySelector('#reference-help');
  const fallback = document.querySelector('#reference-inline');
  if (!opener || !panel || !fallback || typeof globalThis.UIPopup?.attach !== 'function' ||
      opener.popoverTargetElement !== panel || !panel.querySelectorAll('button').length ||
      [...panel.querySelectorAll('button')].some(button => button.popoverTargetElement !== panel)) return;
  const events = new AbortController();
  let positioner;
  function inline() {
    const recover = panel.contains(document.activeElement) || document.activeElement === opener;
    events.abort();
    if (panel.matches(':popover-open')) panel.hidePopover();
    positioner?.destroy();
    panel.hidden = true; opener.hidden = true; fallback.hidden = false;
    if (recover) fallback.querySelector('h3').focus();
  }
  try { positioner = UIPopup.attach({ anchor: opener, surface: panel, onUnavailable: inline }); }
  catch { return; }
  opener.addEventListener('click', () => opener.focus(), { signal: events.signal });
  window.addEventListener('pagehide', event => { if (!event.persisted) { positioner.destroy(); events.abort(); } }, { signal: events.signal });
  panel.hidden = false; fallback.hidden = true; opener.hidden = false;
})();
